{"content":"import unittest

from dot_dsl import ATTR, EDGE, NODE, Edge, Graph, Node


class GraphTest(unittest.TestCase):
    def test_empty_graph(self):
        for graph in (Graph(), Graph(None), Graph([])):
            self.assertEqual(graph.nodes, [])
            self.assertEqual(graph.edges, [])
            self.assertEqual(graph.attrs, {})

    def test_graph_items(self):
        graph = Graph([
            (ATTR, "bgcolor", "yellow"),
            (NODE, "a", {"color": "red"}),
            (NODE, "b", {"color": "blue"}),
            (EDGE, "a", "b", {"color": "green"}),
            (EDGE, "b", "a", {}),
        ])
        self.assertEqual(graph.attrs, {"bgcolor": "yellow"})
        self.assertEqual(graph.nodes, [
            Node("a", {"color": "red"}), Node("b", {"color": "blue"})
        ])
        self.assertEqual(graph.edges, [
            Edge("a", "b", {"color": "green"}), Edge("b", "a", {})
        ])

    def test_attributes_update(self):
        graph = Graph([(ATTR, "color", "red"), (ATTR, "color", "blue")])
        self.assertEqual(graph.attrs, {"color": "blue"})

    def test_graphs_have_independent_collections(self):
        first, second = Graph(), Graph()
        first.nodes.append(Node("a", {}))
        first.edges.append(Edge("a", "a", {}))
        first.attrs["color"] = "red"
        self.assertEqual(second.nodes, [])
        self.assertEqual(second.edges, [])
        self.assertEqual(second.attrs, {})

    def test_malformed_graph_data(self):
        for data in (0, False, "", "graph", {}, (), (NODE, "a", {})):
            with self.subTest(data=data):
                with self.assertRaisesRegex(TypeError, "^Graph data malformed$"):
                    Graph(data)

    def test_malformed_graph_items(self):
        for item in ((), None, 1, "node", [NODE, "a", {}]):
            with self.subTest(item=item):
                with self.assertRaisesRegex(TypeError, "^Graph item incomplete$"):
                    Graph([item])

    def test_malformed_nodes(self):
        for item in ((NODE,), (NODE, "a"), (NODE, "a", {}, "extra"),
                     (NODE, 1, {}), (NODE, "a", [])):
            with self.subTest(item=item):
                with self.assertRaisesRegex(ValueError, "^NODE malformed$"):
                    Graph([item])

    def test_malformed_edges(self):
        for item in ((EDGE,), (EDGE, "a", "b"),
                     (EDGE, "a", "b", {}, "extra"), (EDGE, 1, "b", {}),
                     (EDGE, "a", 2, {}), (EDGE, "a", "b", [])):
            with self.subTest(item=item):
                with self.assertRaisesRegex(ValueError, "^EDGE malformed$"):
                    Graph([item])

    def test_malformed_attributes(self):
        for item in ((ATTR,), (ATTR, "color"),
                     (ATTR, "color", "red", "extra"),
                     (ATTR, 1, "red"), (ATTR, "color", 2)):
            with self.subTest(item=item):
                with self.assertRaisesRegex(ValueError, "^ATTR malformed$"):
                    Graph([item])

    def test_unknown_items(self):
        for kind in (99, "NODE", None, []):
            with self.subTest(kind=kind):
                with self.assertRaisesRegex(ValueError, "^Unknown item$"):
                    Graph([(kind,)])


if __name__ == "__main__":
    unittest.main()
